全部用例（正常、引号/Unicode/控制字符、缺参、help、未知参数、负数、`--opt=val`、缩写、`--`）均与可执行文件逐字符一致，退出码相同。

## 生成的工程结构

```
/output
├── test6.mjs            # 入口文件
└── lib
    ├── pyrepr.mjs       # Python repr 格式化（字符串/列表/元组）
    ├── omd.mjs          # OrderedMultiDict（有序多值字典）
    └── argparse.mjs     # argparse 行为克隆
```

## 库文件

**`/output/lib/pyrepr.mjs`** — Python `repr` 语义：单引号优先、含单引号时切换双引号、转义反斜杠/`\n`/`\r`/`\t`、不可打印码点按 `\xXX`/`\uXXXX`/`\UXXXXXXXX` 转义（可打印 Unicode 如 `café`、`中文`、`😀` 原样输出，空格除外于 Zs 类）：

```js
const NON_PRINTABLE = /\p{Cc}|\p{Cf}|\p{Cs}|\p{Co}|\p{Zl}|\p{Zp}|\p{Zs}/u;

export class PyTuple {
  constructor(items) { this.items = items; }
}

export function pyTuple(...items) { return new PyTuple(items); }

function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (cp === 0x20 || !NON_PRINTABLE.test(ch)) out += ch;
    else if (cp < 0x100) out += '\\x' + cp.toString(16).padStart(2, '0');
    else if (cp < 0x10000) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out + quote;
}

export function pyRepr(value) {
  if (typeof value === 'string') return reprStr(value);
  if (value instanceof PyTuple) {
    const inner = value.items.map(pyRepr).join(', ');
    if (value.items.length === 0) return '()';
    if (value.items.length === 1) return `(${inner},)`;
    return `(${inner})`;
  }
  if (Array.isArray(value)) return `[${value.map(pyRepr).join(', ')}]`;
  return String(value);
}
```

**`/output/lib/omd.mjs`** — `add` 追加全部键值对；`getlist` 返回该键全部值；`keys()` 去重且按首次出现序；`items()` 每键只取**最后**一个值（与实测一致）；`toString()` 输出含全部对的 repr：

```js
import { pyRepr, pyTuple } from './pyrepr.mjs';

export class OMD {
  constructor() { this.pairs = []; }

  add(key, value) { this.pairs.push([key, value]); }

  getlist(key) {
    return this.pairs.filter(([k]) => k === key).map(([, v]) => v);
  }

  keys() {
    const seen = new Set();
    const out = [];
    for (const [k] of this.pairs) {
      if (!seen.has(k)) { seen.add(k); out.push(k); }
    }
    return out;
  }

  items() {
    const last = new Map();
    for (const [k, v] of this.pairs) last.set(k, v);
    return [...last.entries()].map(([k, v]) => pyTuple(k, v));
  }

  toString() {
    const all = this.pairs.map(([k, v]) => pyTuple(k, v));
    return `OrderedMultiDict(${pyRepr(all)})`;
  }
}
```

**`/output/lib/argparse.mjs`** — 忠实复刻 argparse：支持 `--opt val` / `--opt=val` / 无歧义前缀缩写 / `--` 分隔；`-` 开头的 token 视为选项（负数除外）；required 检查先于 unrecognized；错误写 stderr 退出码 2，`-h` 写 stdout 退出码 0：

```js
const OPTIONS = [
  { flag: '--a', metavar: 'A' },
  { flag: '--b', metavar: 'B' },
  { flag: '--c', metavar: 'C' },
];
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) { return `usage: ${prog} [-h] --a A --b B --c C`; }

function error(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(usageLine(prog) + '\n\n');
  process.stdout.write('options:\n');
  process.stdout.write('  -h, --help  show this help message and exit\n');
  for (const o of OPTIONS) process.stdout.write(`  ${o.flag} ${o.metavar}\n`);
  process.exit(0);
}

function isOptionLike(token) {
  return token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER.test(token);
}

function matchLong(name, prog) {
  const candidates = ['--help', ...OPTIONS.map((o) => o.flag)].filter(
    (f) => f === name || f.startsWith(name)
  );
  if (candidates.length === 1) return candidates[0];
  if (candidates.length > 1) {
    error(prog, `ambiguous option: ${name} could match ${candidates.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];
  let optionsEnded = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    if (!optionsEnded && token === '--') { optionsEnded = true; continue; }

    if (!optionsEnded && token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const flag = matchLong(name, prog);
      if (flag === null) { extras.push(token); continue; }
      if (flag === '--help') printHelp(prog);
      if (eq !== -1) { values[flag] = token.slice(eq + 1); continue; }
      const next = argv[i + 1];
      if (next === undefined || isOptionLike(next)) {
        error(prog, `argument ${flag}: expected one argument`);
      }
      values[flag] = next; i++; continue;
    }

    if (!optionsEnded && token === '-h') printHelp(prog);
    if (!optionsEnded && isOptionLike(token)) { extras.push(token); continue; }
    extras.push(token);
  }

  const missing = OPTIONS.filter((o) => !(o.flag in values)).map((o) => o.flag);
  if (missing.length > 0) {
    error(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    error(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }
  return { a: values['--a'], b: values['--b'], c: values['--c'] };
}
```

## 入口文件 `/output/test6.mjs`

```js
import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { OMD } from './lib/omd.mjs';
import { pyRepr } from './lib/pyrepr.mjs';

const prog = basename(process.argv[1]);
const args = parseArgs(process.argv.slice(2), prog);

const omd = new OMD();  // 创建有序多值字典
console.log(String(omd));
omd.add(args.a, args.b);  // 添加键值对（add方法返回None）
console.log(String(omd));
omd.add(args.a, args.c);  // 添加相同键的第二个值
console.log(String(omd));
const result1 = omd.getlist(args.a);  // 获取键的所有值
console.log(pyRepr(result1));
const result2 = omd.keys();  // 获取所有键
console.log(pyRepr(result2));
const result3 = omd.items();  // 获取所有键值对
console.log(pyRepr(result3));
```

## 验证结果

- 正常输出（含 `--opt=val`、引号、`café/中文/😀`、控制字符 `\x01\x7f\n`）：与 `/workspace/dataset/test6_executable` diff 完全一致
- 错误路径（缺参、缺值、未知参数、多余位置参数、`-h`/`--help`/缩写、负数值）：stdout、stderr、退出码全部一致（usage 中 prog 名按 argparse 惯例取脚本 basename，即 `test6.mjs`，对应可执行文件的 `test6_executable`）

运行方式：`node /output/test6.mjs --a foo --b bar --c baz`
